mapper.select:
SELECT T1.FINPROD_ID, T1.FINPROD_NAME, T1.FINPROD_ABBR, T1.FINPROD_TYPE2, T1.FINPROD_MARKET_ID, T1.ISSUER, T1.ISSUE_AMT, T1.VDATE, T1.MDATE, T1.CCY, T2.TYPE_6,
T2.TYPE_9, T2.TYPE_10, T2.TYPE_11, T2.TYPE_12,
T3.CUSTOMER_NAME ISSUER_NAME,
FPR.recommender recommender, FPR.recommenderName recommenderName,
T5.RATE*100 RATE, T7.CUSTOMER_NAME SPONSOR_NAME FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T3 ON T1.ISSUER = T3.CUSTOMER_ID LEFT JOIN FIN_CASH_INFO T4 ON T4.FINPROD_ID = T1.FINPROD_ID
AND T4.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T5 ON T5.CASH_ID = T4.CASH_ID AND T5.EFF_DATE = T1.VDATE
LEFT JOIN ( SELECT FPR.FINPROD_ID, listagg(FPR.RECOMMENDER,'，') within group(order by FPR.RECOMMENDER) recommender, listagg(MCP.COUNTER_NAME,'，') within group(order by FPR.RECOMMENDER) recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO T7 ON T7.CUSTOMER_ID = T1.SPONSOR
AND T1.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T2.TYPE_6 = #{type6,jdbcType=VARCHAR}
AND T2.TYPE_9 in
#{item}
AND T2.TYPE_10 in
#{item}
AND T2.TYPE_11 in
#{item}
AND T1.CCY = #{ccy,jdbcType=VARCHAR}
AND T1.VDATE >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND T1.VDATE <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND (T1.MDATE >= TO_DATE(#{mdateStart},'YYYY-MM-DD') or T1.MDATE is null)
AND (T1.MDATE <= TO_DATE(#{mdateEnd},'YYYY-MM-DD') or T1.MDATE is null)
AND T1.FINPROD_MARKET_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%')
AND T1.FINPROD_NAME like concat(concat('%',#{finprodName,jdbcType=VARCHAR}),'%')
AND T1.ISSUER = #{issuer,jdbcType=VARCHAR}

select T1.ISSUE_AMT ISSUE_AMT, T1.CONTRACT_NO, T1.SPONSOR,
,T2.TYPE_6,T2.TYPE_7,T5.ASSET_PROVIDER,T3.CALENDAR_NAME,T4.COUNTER_NAME ASSET_PROVIDER_NAME,T6.CUSTOMER_NAME ISSUER_NAME,T8.YIELD*100 referRate
,T2.TYPE_9,T2.TYPE_10,T2.TYPE_11,T2.TYPE_12,
T5.ACTUAL_CREDIT_PROVID actualCreditProvid, T1.ISSUER issuer,
/*FPR.RECOMMENDER recommender,*/
T5.TRIAL_NO, T5.ASSET_SOURCE, T9.POST_ORG, T10.REGULATORY_RATING, T11.BUYOUT_RATE*100 BUYOUT_RATE, T10.IS_RECEIPT, T10.IS_INNER_ADV, T10.IS_INADVANCE isInAdvance from FIN_PRODUCT T1
left join FIN_PRODUCT_TYPE T2 on T1.FINPROD_ID = T2.FINPROD_ID left join PA_FIN_PRODUCT T5 on T5.FINPROD_ID = T1.FINPROD_ID left join MST_CALENDAR_INFO T3 on T3.CALENDAR_ID = T1.CALENDAR_ID left join MST_COUNTER_PARTY T4 on T4.COUNTER_ID = T5.ASSET_PROVIDER left join MST_CUSTOMER_INFO T6 on T6.CUSTOMER_ID = T1.ISSUER left join FIN_CASH_INFO T7 on T7.FINPROD_ID=T1.FINPROD_ID
and T7.FINPROD_TYPE= #{finprodType,jdbcType=VARCHAR}
and T7.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
left join FIN_CASH_CALC_RULE T8 on T8.CASH_ID=T7.CASH_ID and T8.EFF_DATE = T1.VDATE
/*LEFT JOIN FIN_PRODUCT_RECOMMENT FPR ON FPR.FINPROD_ID = T1.FINPROD_ID*/
left join FIN_POST_INVEST_INFO T9 on T9.FINPROD_ID=T1.FINPROD_ID left join FIN_PRODUCT_ADD T10 on T10.FINPROD_ID=T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT_BUYOUT_RATE T11 ON T11.FINPROD_ID = T1.FINPROD_ID
T1.FINPROD_ID = #{finprodId}
AND T1.FINPROD_MARKET_ID = #{finprodMarketId} AND T1.FINPROD_TYPE2 = #{finprodType2}

select  CUSTOMER_ID id,
CUSTOMER_NAME text
from MST_CUSTOMER_INFO


		and (CUSTOMER_ID like concat(concat('%',#{search}),'%')
		or CUSTOMER_NAME like concat(concat('%',#{search}),'%'))


		and CUSTOMER_TYPE = #{CUSTOMER_TYPE}



		and (IS_DEPOSIT_BANK = #{IS_DEPOSIT_BANK}
		or IS_FINANCIER = #{IS_FINANCIER})



		and CUSTOMER_ID = #{initValue}
